"use server";

import { t } from "@/i18n";
import type { ReviewData } from "@/lib/mock/review";
import { computeLife } from "@/server/life/compute";
import { addDays, localDate, mondayOf } from "@/server/life/dates";
import { ensureFolderPath, updateItem } from "@/server/repo";
import { computeReview, WEEKLY_FOLDER } from "@/server/review/compute";
import { reviewMarkdown, type SaveReviewInput } from "@/server/review/markdown";
import { runData, sourceFor, type DataResult } from "./run";

/*
 * Weekly review, live (WP-I). The digest itself is generated by POST /api/digest (client:
 * generateDigest) and saved in 90_Digests; this module computes the review and saves its result
 * as the Markdown note 10_Notes/Weekly/YYYY-Www.md (type note, slug = week) plus tasks for the
 * chosen focus points that are not tasks yet.
 */

export async function loadReview(): Promise<DataResult<ReviewData>> {
  return runData("loadReview", async (ctx) => {
    const src = await sourceFor(ctx);
    const data = computeReview(src, computeLife(src));
    const { data: note, error } = await ctx.client
      .from("knowledge_items")
      .select("id")
      .eq("user_id", ctx.userId)
      .eq("folder_path", WEEKLY_FOLDER)
      .eq("slug", data.review.isoWeek)
      .maybeSingle();
    if (error) throw new Error(error.message);
    return { ...data, saved: Boolean(note) };
  });
}

/** Saves the week's review note (upsert by week) and creates tasks for new focus points. */
export async function saveWeeklyReview(
  input: SaveReviewInput,
): Promise<DataResult<{ id: string; file: string; tasks: number }>> {
  return runData("saveWeeklyReview", async (ctx) => {
    if (!/^\d{4}-W\d{2}$/.test(input.isoWeek)) throw new Error(t("Invalid week"));
    if (input.focus.length > 5 || input.answers.length > 5) throw new Error(t("Too many entries"));
    const today = localDate(ctx.now, ctx.timeZone);
    const markdown = reviewMarkdown(input, today);
    const folder = await ensureFolderPath(ctx.client, ctx.userId, WEEKLY_FOLDER);
    const { data: existing, error } = await ctx.client
      .from("knowledge_items")
      .select("id")
      .eq("user_id", ctx.userId)
      .eq("folder_path", folder.folder_path)
      .eq("slug", input.isoWeek)
      .maybeSingle();
    if (error) throw new Error(error.message);
    let id: string;
    if (existing) {
      id = existing.id;
      await updateItem(ctx.client, ctx.userId, id, { content_md: markdown, title: input.title });
    } else {
      id = crypto.randomUUID();
      const ins = await ctx.client.from("knowledge_items").insert({
        id,
        user_id: ctx.userId,
        type: "note",
        source_platform: "manual",
        title: input.title,
        slug: input.isoWeek,
        content_md: markdown,
        folder_id: folder.id,
        folder_path: folder.folder_path,
        is_manual_placement: true,
        tags: ["weekly-review"],
        metadata: { week: input.isoWeek, kind: "weekly_review" },
        status: "processed",
      });
      if (ins.error) throw new Error(ins.error.message);
    }
    // Focus points that are not tasks yet become tasks due Friday next week.
    const due = addDays(mondayOf(today), 11);
    const fresh = input.focus
      .filter((f) => !f.taskId)
      .map((f) => f.t.trim())
      .filter(Boolean);
    let tasks = 0;
    if (fresh.length) {
      const { data: have, error: e2 } = await ctx.client
        .from("action_items")
        .select("title")
        .eq("user_id", ctx.userId)
        .neq("status", "done")
        .in("title", fresh);
      if (e2) throw new Error(e2.message);
      const known = new Set((have ?? []).map((r) => r.title));
      const rows = fresh
        .filter((t) => !known.has(t))
        .map((title) => ({
          user_id: ctx.userId,
          title,
          status: "open",
          priority: "high",
          due_date: due,
          source_item_id: id,
        }));
      if (rows.length) {
        const ins = await ctx.client.from("action_items").insert(rows);
        if (ins.error) throw new Error(ins.error.message);
        tasks = rows.length;
      }
    }
    return { id, file: `${folder.folder_path}/${input.isoWeek}.md`, tasks };
  });
}

/** Moves an open task into next week (due Monday next week). */
export async function postponeTask(id: string): Promise<DataResult<{ due: string }>> {
  return runData("postponeTask", async (ctx) => {
    const due = addDays(mondayOf(localDate(ctx.now, ctx.timeZone)), 7);
    const { error } = await ctx.client
      .from("action_items")
      .update({ due_date: due })
      .eq("user_id", ctx.userId)
      .eq("id", id);
    if (error) throw new Error(error.message);
    return { due };
  });
}
